mapper.select:
SELECT u.id, u.username, u.nickname, u.phone, u.gender, u.avatar, u.status, u.email, u.dept_id, d.name AS dept_name, string_agg(DISTINCT r.name, ',') AS roleNames, u.create_time FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id AND d.deleted = 0 LEFT JOIN sys_user_role sur ON u.id = sur.user_id LEFT JOIN sys_role r ON sur.role_id = r.id AND r.deleted = 0
u.deleted = 0
AND ( u.username LIKE CONCAT('%', #{q.keywords}, '%') OR u.nickname LIKE CONCAT('%', #{q.keywords}, '%') OR u.phone LIKE CONCAT('%', #{q.keywords}, '%') )
AND u.status = #{q.status}
AND u.dept_id = #{q.deptId}
GROUP BY u.id, u.username, u.nickname, u.phone, u.gender, u.avatar, u.status, u.email, u.dept_id, d.name, u.create_time ORDER BY u.create_time DESC
